440	// branchReviewedAtHead reports whether the current branch's HEAD commit is
441	// itself a review commit (CommitsSince == 0 on the scanner). Returns a short
442	// human-readable meta string for the re-run prompt.
443	func branchReviewedAtHead(ctx context.Context) (bool, string) {
444		info, ok, err := findMostRecentReview(ctx)
445		if err != nil || !ok {
446			return false, ""
447		}
448		if info.CommitsSince != 0 {
449			return false, ""
450		}
