func AppendReviewTrailers(message string, md ReviewMetadata) string {
	trailers := []struct {
		key, val string
	}{
		{ReviewByTrailerKey, md.By},
		{ReviewAgentTrailerKey, md.Agent},
		{ReviewSkillsTrailerKey, strings.Join(md.Skills, ",")},
