250	func TestCreateReviewCommit(t *testing.T) {
251		// NOTE: uses t.Chdir, so no t.Parallel.
252		tmp := t.TempDir()
253		testutil.InitRepo(t, tmp)
254		testutil.WriteFile(t, tmp, "f.txt", "x")
255		testutil.GitAdd(t, tmp, "f.txt")
256		testutil.GitCommit(t, tmp, "init")
257		t.Chdir(tmp)
258	
259		ctx := context.Background()
260	
261		// Record HEAD before the review commit.
262		repo, err := git.PlainOpen(tmp)
263		if err != nil {
264			t.Fatalf("PlainOpen: %v", err)
265		}
266		headBefore, err := repo.Head()
267		if err != nil {
268			t.Fatalf("Head: %v", err)
269		}
270		oldHEAD := headBefore.Hash()
271	
272		md := trailers.ReviewMetadata{
273			By:     "tester@example.com",
274			Status: trailers.ReviewStatusClosed,
275		}
276		hash, err := createReviewCommit(ctx, md)
277		if err != nil {
278			t.Fatalf("createReviewCommit: %v", err)
279		}
280		if hash == (plumbing.Hash{}) {
281			t.Fatal("returned zero hash")
282		}
283	
284		// Branch HEAD should have advanced.
285		headAfter, err := repo.Head()
286		if err != nil {
287			t.Fatalf("Head after: %v", err)
288		}
289		if headAfter.Hash() != hash {
290			t.Errorf("HEAD = %s, want %s", headAfter.Hash(), hash)
291		}
292		if headAfter.Hash() == oldHEAD {
293			t.Error("HEAD did not advance")
294		}
295	
296		// New commit's parent should be the old HEAD.
297		commit, err := repo.CommitObject(hash)
298		if err != nil {
299			t.Fatalf("CommitObject: %v", err)
300		}
301		if len(commit.ParentHashes) != 1 || commit.ParentHashes[0] != oldHEAD {
302			t.Errorf("parent = %v, want [%s]", commit.ParentHashes, oldHEAD)
303		}
304	
305		// Tree should equal parent's tree (empty commit).
306		parent, err := repo.CommitObject(oldHEAD)
307		if err != nil {
308			t.Fatalf("parent CommitObject: %v", err)
309		}
310		if commit.TreeHash != parent.TreeHash {
311			t.Errorf("tree hash changed: %s != %s", commit.TreeHash, parent.TreeHash)
312		}
313	
314		// Commit message should contain the review trailer.
315		if !strings.Contains(commit.Message, trailers.ReviewByTrailerKey) {
316			t.Errorf("commit message missing %q trailer; got:\n%s", trailers.ReviewByTrailerKey, commit.Message)
317		}
318	}
