17	func TestScaffoldSearchSubagent_CreatesManagedFiles(t *testing.T) {
18		testCases := []struct {
19			name        string
20			scaffoldFn  func() (searchSubagentScaffoldResult, error)
21			relPath     string
22			wantSnippet string
23		}{
24			{
25				name: "claude",
26				scaffoldFn: func() (searchSubagentScaffoldResult, error) {
27					return scaffoldSearchSubagent(context.Background(), claudecode.NewClaudeCodeAgent())
28				},
29				relPath:     filepath.Join(".claude", "agents", "entire-search.md"),
30				wantSnippet: "tools: Bash",
31			},
32			{
33				name: "codex",
34				scaffoldFn: func() (searchSubagentScaffoldResult, error) {
35					return scaffoldSearchSubagent(context.Background(), codex.NewCodexAgent())
36				},
37				relPath:     filepath.Join(".codex", "agents", "entire-search.toml"),
38				wantSnippet: `sandbox_mode = "read-only"`,
39			},
40			{
41				name: "gemini",
42				scaffoldFn: func() (searchSubagentScaffoldResult, error) {
43					return scaffoldSearchSubagent(context.Background(), geminicli.NewGeminiCLIAgent())
44				},
45				relPath:     filepath.Join(".gemini", "agents", "entire-search.md"),
46				wantSnippet: "- run_shell_command",
47			},
48		}
49	
50		for _, tc := range testCases {
51			t.Run(tc.name, func(t *testing.T) {
52				tmpDir := setupTestDir(t)
53	
54				result, err := tc.scaffoldFn()
55				if err != nil {
56					t.Fatalf("scaffoldSearchSubagent() error = %v", err)
57				}
58				if result.Status != searchSubagentCreated {
59					t.Fatalf("scaffoldSearchSubagent() status = %q, want %q", result.Status, searchSubagentCreated)
60				}
61				if result.RelPath != tc.relPath {
62					t.Fatalf("scaffoldSearchSubagent() relPath = %q, want %q", result.RelPath, tc.relPath)
63				}
64	
65				data, err := os.ReadFile(filepath.Join(tmpDir, tc.relPath))
66				if err != nil {
67					t.Fatalf("failed to read scaffolded file: %v", err)
68				}
69				content := string(data)
70				if !strings.Contains(content, entireManagedSearchSubagentMarker) {
71					t.Fatal("scaffolded file should contain Entire-managed marker")
72				}
73				assertStrictJSONSearchInstructions(t, content)
74				if !strings.Contains(content, tc.wantSnippet) {
75					t.Fatalf("scaffolded file missing expected snippet %q", tc.wantSnippet)
76				}
77			})
78		}
79	}
